B.aoz=new A.I(328,B.WA)
B.VJ=s(["Deleting an item from a folder now leaves it in its other folders \u2014 it only drops out of the one you deleted it from."],t.s)
B.apd=new A.I(327,B.VJ)
B.Za=s(["Say \u201cresume dictation\u201d (or \u201cresume dictating\u201d) to pick your note back up \u2014 and the command chip now says so."],t.s)
B.apb=new A.I(326,B.Za)
